// mapear Student (modelo) a ParentDashboardState.ChildInfo simplificado
private fun mapStudentToDashboard(student: Student, index: Int, all: List<Student>): ParentDashboardState {
    val name = if (student.nombre.isNotBlank()) student.nombre else (student.id)
    val grade = listOfNotNull(student.curso.takeIf { it.isNotBlank() }, student.grupo.takeIf { it.isNotBlank() }).joinToString("-")
    val child = ChildInfo(
        studentName = name,
        studentGrade = grade.ifBlank { "-" },
        recentGrades = emptyList(),
        pendingPayments = emptyList(),
        attendancePercentage = 0.0,
        pendingTasks = 0,
        notifications = emptyList()
    )
    return ParentDashboardState(
        studentName = child.studentName,
        studentGrade = child.studentGrade,
        recentGrades = child.recentGrades,
        pendingPayments = child.pendingPayments,
        attendancePercentage = child.attendancePercentage,
        pendingTasks = child.pendingTasks,
        notifications = child.notifications,
        children = all.map { s -> ChildInfo(s.nombre.ifBlank { s.id }, listOfNotNull(s.curso.takeIf { it.isNotBlank() }, s.grupo.takeIf { it.isNotBlank() }).joinToString("-")) },
        selectedChildIndex = index,
        loading = false
    )
}

package com.example.appcolegios.parent

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.clickable
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.*
import androidx.compose.material.icons.automirrored.filled.Assignment
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import java.util.Locale
import androidx.lifecycle.viewmodel.compose.viewModel
import com.example.appcolegios.perfil.ProfileViewModel
import com.example.appcolegios.data.model.Student
import com.example.appcolegios.data.FirestoreRepository
import com.google.firebase.Timestamp
import java.text.SimpleDateFormat

// Restaurar data classes necesarias
data class Grade(
    val subject: String,
    val grade: Double,
    val period: String
)

data class Payment(
    val concept: String,
    val amount: Double,
    val dueDate: String,
    val status: String
)

data class ParentNotification(
    val title: String,
    val message: String,
    val date: String,
    val read: Boolean
)

// Representación de un hijo con los mismos campos de información
data class ChildInfo(
    val studentName: String,
    val studentGrade: String,
    val recentGrades: List<Grade> = emptyList(),
    val pendingPayments: List<Payment> = emptyList(),
    val attendancePercentage: Double = 0.0,
    val pendingTasks: Int = 0,
    val notifications: List<ParentNotification> = emptyList()
)

data class ParentDashboardState(
    val studentName: String = "",
    val studentGrade: String = "",
    val recentGrades: List<Grade> = emptyList(),
    val pendingPayments: List<Payment> = emptyList(),
    val attendancePercentage: Double = 0.0,
    val pendingTasks: Int = 0,
    val notifications: List<ParentNotification> = emptyList(),
    val children: List<ChildInfo> = emptyList(),
    val selectedChildIndex: Int = 0,
    val loading: Boolean = true
)

@Composable
fun ParentHomeScreen() {
    // Usar ProfileViewModel para obtener hijos reales
    val profileVm: ProfileViewModel = viewModel()
    val childrenList: List<Student> by profileVm.children.collectAsState(initial = emptyList())
    val selectedIndexState: Int? by profileVm.selectedChildIndex.collectAsState(initial = null)
    val selectedChildIndex = selectedIndexState ?: 0
    val studentResult by profileVm.student.collectAsState(initial = null)
    val currentStudent = studentResult?.getOrNull()

    var showSelectChildDialog by remember { mutableStateOf(false) }

    // Estado calculado a partir del hijo seleccionado
    var state by remember { mutableStateOf(ParentDashboardState(loading = true)) }

    // Cuando cambie el student seleccionado en el ViewModel, actualizar el dashboard
    LaunchedEffect(currentStudent, childrenList) {
        if (currentStudent != null) {
            // Cargar datos reales desde Firestore: notas, pagos y notificaciones (misma lógica que las pantallas correspondientes)
            state = state.copy(loading = true)
            try {
                val repo = FirestoreRepository()
                val childId = currentStudent.id

                // 1) Notas: students/{childId}/grades
                val gradesDocs = try { repo.getSubcollectionDocuments("students", childId, "grades") } catch (_: Exception) { emptyList() }
                val recentGrades = gradesDocs.mapNotNull { doc ->
                    try {
                        val subject = doc["materia"] as? String ?: doc["subject"] as? String ?: doc["name"] as? String ?: ""
                        val period = doc["periodo"] as? String ?: doc["period"] as? String ?: ""
                        val gradeVal: Double = run {
                            val candidates = listOf("score", "calificacion", "grade")
                            var raw: Any? = null
                            for (f in candidates) {
                                if (doc.containsKey(f)) { raw = doc[f]; break }
                            }
                            when (raw) {
                                is Number -> raw.toDouble()
                                is String -> raw.toDoubleOrNull() ?: 0.0
                                else -> (doc["calificacion"] as? Number)?.toDouble() ?: (doc["grade"] as? Number)?.toDouble() ?: 0.0
                            }
                        }
                        Grade(subject = subject, grade = gradeVal, period = period)
                    } catch (_: Exception) { null }
                }.take(3)

                // 2) Pagos: collection 'pagos' where studentId == childId
                val pagosDocs = try { repo.queryWhereEqual("pagos", "studentId", childId) } catch (_: Exception) { emptyList() }
                val pendingPayments = pagosDocs.mapNotNull { doc ->
                    try {
                        val titulo = doc["titulo"] as? String ?: doc["title"] as? String ?: "Pago"
                        val monto = when (val m = doc["monto"]) {
                            is Number -> m.toDouble()
                            is String -> m.toDoubleOrNull() ?: 0.0
                            else -> 0.0
                        }
                        val fecha = when (val f = doc["fecha"]) {
                            is Timestamp -> f.toDate()
                            is java.util.Date -> f
                            else -> java.util.Date()
                        }
                        val sdf = SimpleDateFormat("dd/MM/yyyy", java.util.Locale.getDefault())
                        val dueStr = sdf.format(fecha)
                        val estado = doc["estado"] as? String ?: doc["status"] as? String ?: "Pendiente"
                        Payment(concept = titulo, amount = monto, dueDate = dueStr, status = estado)
                    } catch (_: Exception) { null }
                }.take(3)

                // 3) Notificaciones: users/{childId}/notifications
                val notiDocs = try { repo.getSubcollectionDocuments("users", childId, "notifications") } catch (_: Exception) { emptyList() }
                val notifs = notiDocs.mapNotNull { doc ->
                    try {
                        val title = doc["titulo"] as? String ?: doc["title"] as? String ?: ""
                        val body = doc["cuerpo"] as? String ?: doc["body"] as? String ?: ""
                        val tsField = doc["fechaHora"] ?: doc["createdAt"] ?: doc["date"]
                        val date = when (tsField) {
                            is Timestamp -> tsField.toDate()
                            is java.util.Date -> tsField
                            else -> java.util.Date()
                        }
                        val sdf = SimpleDateFormat("dd/MM/yyyy HH:mm", java.util.Locale.getDefault())
                        ParentNotification(title = title, message = body, date = sdf.format(date), read = (doc["leida"] as? Boolean) ?: false)
                    } catch (_: Exception) { null }
                }.sortedByDescending { it.date }.take(3)

                // 4) Asistencia: calcular porcentaje (buscar docs en colección 'attendance' y contar presentes)
                val attendDocs = try { repo.queryWhereEqual("attendance", "studentId", childId) } catch (_: Exception) { emptyList() }
                var attendancePct = 0.0
                try {
                    if (attendDocs.isNotEmpty()) {
                        var total = 0
                        var present = 0
                        for (d in attendDocs) {
                            total += 1
                            val records = d["records"] as? Map<*, *>
                            val raw = records?.get(childId) as? String
                            if (raw != null && raw.uppercase() == "PRESENTE") present += 1
                        }
                        if (total > 0) attendancePct = (present.toDouble() / total.toDouble()) * 100.0
                    }
                } catch (_: Exception) { attendancePct = 0.0 }

                // Actualizar estado
                state = ParentDashboardState(
                    studentName = currentStudent.nombre.ifBlank { currentStudent.id },
                    studentGrade = listOfNotNull(currentStudent.curso.takeIf { it.isNotBlank() }, currentStudent.grupo.takeIf { it.isNotBlank() }).joinToString("-"),
                    recentGrades = recentGrades.toList(),
                    pendingPayments = pendingPayments.toList(),
                    attendancePercentage = attendancePct,
                    pendingTasks = 0,
                    notifications = notifs.toList(),
                    children = childrenList.map { s -> ChildInfo(s.nombre.ifBlank { s.id }, listOfNotNull(s.curso.takeIf { it.isNotBlank() }, s.grupo.takeIf { it.isNotBlank() }).joinToString("-")) },
                    selectedChildIndex = selectedChildIndex,
                    loading = false
                )
            } catch (e: Exception) {
                state = ParentDashboardState(loading = false, children = childrenList.map { s -> ChildInfo(s.nombre.ifBlank { s.id }, listOfNotNull(s.curso.takeIf { it.isNotBlank() }, s.grupo.takeIf { it.isNotBlank() }).joinToString("-")) })
            }
        } else if (childrenList.isNotEmpty()) {
            // si no hay student pero hay hijos, usar el primero
            profileVm.selectChildAtIndex(0)
        } else {
            state = ParentDashboardState(loading = false, children = emptyList())
        }
    }

    if (state.loading) {
        Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
            CircularProgressIndicator()
        }
    } else {
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Header con info del estudiante
            item {
                StudentInfoCard(
                    studentName = state.studentName,
                    grade = state.studentGrade,
                    onClick = { showSelectChildDialog = true }
                )
            }

            // Resumen académico
            item {
                AcademicSummaryCard(
                    attendancePercentage = state.attendancePercentage,
                    pendingTasks = state.pendingTasks,
                    averageGrade = if (state.recentGrades.isEmpty()) 0.0 else state.recentGrades.map { it.grade }.average()
                )
            }

            // Notas recientes
            item {
                Text(
                    "Notas Recientes",
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold
                )
            }

            items(state.recentGrades) { grade ->
                GradeCard(grade)
            }

            // Pagos pendientes
            item {
                Text(
                    "Pagos",
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold
                )
            }

            items(state.pendingPayments) { payment ->
                PaymentCard(payment)
            }

            // Notificaciones
            item {
                Text(
                    "Notificaciones",
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold
                )
            }

            items(state.notifications.take(3)) { notification ->
                NotificationCard(notification)
            }
        }

        // Diálogo para seleccionar otro hijo (fuera del LazyColumn, en contexto composable)
        if (showSelectChildDialog) {
            var sel by remember { mutableStateOf(selectedChildIndex) }
            AlertDialog(
                onDismissRequest = { showSelectChildDialog = false },
                title = { Text("Selecciona estudiante") },
                text = {
                    Column {
                        if (childrenList.isEmpty()) Text("No hay hijos asociados") else childrenList.forEachIndexed { index, child ->
                            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 4.dp)
                                .clickable { sel = index }) {
                                RadioButton(selected = sel == index, onClick = { sel = index })
                                Spacer(Modifier.width(8.dp))
                                Column {
                                    Text(child.nombre, fontWeight = FontWeight.SemiBold)
                                    Text("Curso: ${child.curso}", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                }
                            }
                        }
                    }
                },
                confirmButton = {
                    TextButton(onClick = {
                        if (childrenList.isNotEmpty()) {
                            // Actualizamos selección central en ViewModel
                            profileVm.selectChildAtIndex(sel)
                        }
                        showSelectChildDialog = false
                    }) { Text("Aceptar") }
                },
                dismissButton = { TextButton(onClick = { showSelectChildDialog = false }) { Text("Cancelar") } }
            )
        }
    }
}

